/* Arefi ITPraxis – Kurs Prüfungsvorbereitung Fachinformatiker Systemintegration (AP1/AP2). [fa, de, en]
   Prüfungsstruktur geprüft an IHK-/DIHK-Unterlagen (FIAusbV 2020), Stand November 2026. */
(() => {
'use strict';
const C = window.ArefiKAp = window.ArefiKAp || { modules: [] };
C.modules.push(

{
  id: 'ap-ueberblick', part: 1,
  title: ['ساختار آزمون و برنامهٔ مطالعه', 'Prüfungsaufbau und Lernplan', 'Exam structure and study plan'],
  goal: ['ساختار آزمون دوبخشی Fachinformatiker Systemintegration، وزن هر بخش و قواعد قبولی را بدانی و یک برنامهٔ مطالعهٔ ۱۲ هفته‌ای واقع‌بینانه بسازی.', 'Du kennst Aufbau, Gewichtung und Bestehensregeln der gestreckten Abschlussprüfung Fachinformatiker Systemintegration und erstellst einen realistischen 12-Wochen-Lernplan.', 'Know the structure, weighting and pass rules of the two-part Fachinformatiker Systemintegration exam and build a realistic 12-week study plan.'],
  why: ['کسی که می‌داند امتیاز از کجا می‌آید، وقتش را درست تقسیم می‌کند: پروژه نیمی از کل نمره است و در آزمون‌های کتبی، سؤال‌ها از سال‌های قبل الگو دارند.', 'Wer weiß, woher die Punkte kommen, verteilt seine Zeit richtig: das Projekt macht die Hälfte der Note aus, und die schriftlichen Prüfungen folgen Mustern früherer Jahrgänge.', 'Knowing where points come from lets you spend time well: the project is half the grade, and written exams follow patterns from previous years.'],
  know: [
    ['بخش ۱ (حدود وسط آموزش): «Einrichten eines IT-gestützten Arbeitsplatzes»، کتبی با سؤال‌های باز، ۹۰ دقیقه، ۲۰٪ نمرهٔ نهایی.', 'Teil 1 (etwa zur Mitte der Ausbildung): „Einrichten eines IT-gestützten Arbeitsplatzes“, schriftlich mit offenen Aufgaben, 90 Minuten, 20 % der Endnote.', 'Part 1 (around mid-training): “setting up an IT-supported workplace”, written with open questions, 90 minutes, 20% of the final grade.'],
    ['بخش ۲ (پایان آموزش): پروژهٔ شرکتی «Planen und Umsetzen eines Projektes der Systemintegration» حداکثر ۴۰ ساعت به‌اضافهٔ مستندسازی، سپس ارائهٔ ۱۵ دقیقه و گفت‌وگوی تخصصی ۱۵ دقیقه، روی هم ۵۰٪.', 'Teil 2 (Ende der Ausbildung): betriebliche Projektarbeit „Planen und Umsetzen eines Projektes der Systemintegration“ mit höchstens 40 Stunden plus Dokumentation, danach 15 Minuten Präsentation und 15 Minuten Fachgespräch – zusammen 50 %.', 'Part 2 (end of training): company project “planning and implementing a system integration project”, max 40 hours plus documentation, then a 15-minute presentation and 15-minute technical discussion – 50% together.'],
    ['کتبی بخش ۲: «Konzeption und Administration von IT-Systemen» ۹۰ دقیقه ۱۰٪، «Analyse und Entwicklung von Netzwerken» ۹۰ دقیقه ۱۰٪، و WiSo (اقتصاد و امور اجتماعی) ۶۰ دقیقه چندگزینه‌ای ۱۰٪.', 'Schriftlich in Teil 2: „Konzeption und Administration von IT-Systemen“ 90 Minuten 10 %, „Analyse und Entwicklung von Netzwerken“ 90 Minuten 10 % und WiSo (Wirtschafts- und Sozialkunde) 60 Minuten gebunden 10 %.', 'Written in part 2: “design and administration of IT systems” 90 min 10%, “analysis and development of networks” 90 min 10% and WiSo (economics and social studies) 60 min multiple choice 10%.'],
    ['قواعد قبولی (به‌طور خلاصه): کل آزمون و کل بخش ۲ حداقل «ausreichend» (۵۰٪)، پروژه حداقل ausreichend، در دست‌کم دو بخش کتبی دیگر بخش ۲ ausreichend و در هیچ بخش بخش ۲ «ungenügend» نباشد. امتحان شفاهی تکمیلی در یک بخش کتبی ممکن است. جزئیات را از IHK خودت بگیر.', 'Bestehen (vereinfacht): Gesamtergebnis und Teil 2 jeweils mindestens „ausreichend“ (50 %), Projekt mindestens ausreichend, in mindestens zwei der übrigen Bereiche von Teil 2 ausreichend und in keinem Bereich von Teil 2 „ungenügend“. Eine mündliche Ergänzungsprüfung in einem schriftlichen Bereich ist möglich. Details bei der eigenen IHK erfragen.', 'Passing (simplified): overall and part 2 each at least “ausreichend” (50%), project at least ausreichend, at least two of the other part 2 areas ausreichend and no part 2 area “ungenügend”. An oral supplementary exam in one written area is possible. Get details from your IHK.'],
    ['در اتریش معادل این حرفه کارآموزی «Informationstechnologie – Systemtechnik» با آزمون پایانی Lehrabschlussprüfung (LAP) است؛ موضوعات فنی بسیار مشابه‌اند.', 'In Österreich entspricht dem der Lehrberuf „Informationstechnologie – Systemtechnik“ mit Lehrabschlussprüfung (LAP); die Fachthemen sind sehr ähnlich.', 'In Austria the equivalent is the apprenticeship “Informationstechnologie – Systemtechnik” with the Lehrabschlussprüfung (LAP); the technical topics are very similar.'],
    ['بهترین تمرین: آزمون‌های سال‌های قبل (ZPA/U-Form) زیر زمان واقعی، سپس تحلیل اشتباه‌ها و تکرار همان مبحث.', 'Beste Übung: alte Prüfungen (ZPA/U-Form) unter echter Zeit, danach Fehler auswerten und genau diese Themen wiederholen.', 'Best practice: past exams (ZPA/U-Form) under real time limits, then analyse mistakes and repeat exactly those topics.']],
  lab: { vm: 'Kalender + Notizen + Kurse dieser App', shell: 'Lernplan-Vorlage',
    steps: [
      ['تاریخ آزمون و مهلت ثبت پروژه را از IHK خودت پیدا کن و در تقویم بنویس.', 'در هر مبحث نمونه، با سؤال‌های این برنامه (تمرین‌ساز Subnetting و آزمون تمرینی AP) سطح فعلی‌ات را بسنج.', 'برنامهٔ ۱۲ هفته‌ای بنویس: هر هفته یک تا دو مبحث، یک آزمون قدیمی زیر زمان و یک جلسه مرور.', 'برای هر جلسهٔ مطالعه دورهٔ مرتبط در همین برنامه را مشخص کن (مثلاً شبکه ← دورهٔ شبکه و ذخیره‌سازی).', 'هر هفته پیشرفت را در یادداشت این ماژول ثبت کن.'],
      ['Prüfungstermin und Frist für den Projektantrag bei deiner IHK nachsehen und eintragen.', 'Je Thema mit den Übungen dieser App (Subnetting-Trainer, AP-Übungsquiz) den aktuellen Stand messen.', 'Einen 12-Wochen-Plan schreiben: pro Woche ein bis zwei Themen, eine alte Prüfung unter Zeitdruck und eine Wiederholungseinheit.', 'Für jede Lerneinheit den passenden Kurs dieser App festlegen (z. B. Netzwerk → Lernstrecke Netzwerk und Speicher).', 'Wöchentlich den Fortschritt in der Notiz dieses Moduls festhalten.'],
      ['Look up the exam date and project proposal deadline at your IHK and add them to your calendar.', 'Measure your current level per topic with this app’s exercises (subnetting trainer, AP practice quiz).', 'Write a 12-week plan: one or two topics per week, one timed past exam and one review session.', 'Map each study session to the matching course in this app (e.g. networking → networking and storage course).', 'Record weekly progress in this module’s note.']],
    code: 'Lernplan (Beispiel, 12 Wochen vor Teil 2)\nWoche 1   Netzwerkgrundlagen, OSI/TCP-IP, Subnetting       -> Lernstrecke Netzwerk, Subnetting-Trainer täglich 15 Min.\nWoche 2   VLAN, Routing, NAT, IPv6                         -> Netzwerk Teil 2–3\nWoche 3   Alte Prüfung „Analyse und Entwicklung von Netzwerken“ (90 Min.) + Fehleranalyse\nWoche 4   Server, AD, DNS/DHCP, Rechte                     -> Windows-Server-Kurs\nWoche 5   Linux, Skripte (PowerShell/Bash/Pseudocode)       -> Linux-Kurs, Daten-und-Skripte-Kurs\nWoche 6   Alte Prüfung „Konzeption und Administration“ + Fehleranalyse\nWoche 7   Sicherheit, Datenschutz, Backup, RAID, USV-Rechnung -> Betrieb/Sicherheit, Infrastruktur\nWoche 8   Rechenaufgaben (Übertragung, Speicher, Strom, Kosten) -> Modul „Rechenaufgaben“\nWoche 9   WiSo                                              -> Modul WiSo + AP-Übungsquiz\nWoche 10  Projektpräsentation proben, Fachgesprächsfragen\nWoche 11  Zwei alte Prüfungen komplett unter Zeitdruck\nWoche 12  Nur noch Schwächen wiederholen, ausschlafen\n\nZeitregel in der Prüfung: Punkte ÷ Gesamtpunkte × 90 Min. = Zeitbudget je Aufgabe',
    checks: [
      ['تاریخ‌های آزمون و ثبت پروژه در تقویم است.', 'سطح فعلی‌ات در هر مبحث را با عدد (مثلاً درصد پاسخ درست) داری.', 'برنامهٔ ۱۲ هفته‌ای با آزمون‌های قدیمی زمان‌دار نوشته شد.', 'هر مبحث به یک دوره یا ابزار این برنامه وصل است.'],
      ['Prüfungs- und Antragsfristen stehen im Kalender.', 'Du kennst deinen Stand je Thema als Zahl (z. B. Prozent richtig).', 'Der 12-Wochen-Plan mit zeitgestoppten Altprüfungen steht.', 'Jedes Thema ist mit einem Kurs oder Werkzeug dieser App verknüpft.'],
      ['Exam and proposal deadlines are in your calendar.', 'You know your current level per topic as a number (e.g. percent correct).', 'The 12-week plan with timed past exams is written.', 'Every topic is linked to a course or tool in this app.']] },
  trouble: [
    [['در آزمون کتبی وقت کم می‌آوری.', 'In der schriftlichen Prüfung reicht die Zeit nicht.', 'You run out of time in the written exam.'],
     ['زمان هر سؤال را از امتیازش حساب کن (امتیاز ÷ کل × ۹۰ دقیقه) و از آن بیشتر نمان؛ اول سؤال‌هایی که مطمئنی، بعد بقیه. در تمرین همیشه با زمان‌سنج کار کن. پاسخ کوتاه و دقیق کافی است؛ کتاب ننویس.', 'Zeit je Aufgabe aus den Punkten berechnen (Punkte ÷ gesamt × 90 Min.) und nicht überziehen; erst sichere Aufgaben, dann den Rest. Beim Üben immer mit Stoppuhr. Kurze, präzise Antworten reichen – keine Romane.', 'Compute time per question from its points (points ÷ total × 90 min) and don’t exceed it; do sure questions first. Always practise with a timer. Short precise answers suffice – no essays.']],
    [['با وجود مطالعه، در یک مبحث مدام اشتباه می‌کنی.', 'Trotz Lernen immer wieder Fehler im selben Thema.', 'Despite studying you keep failing the same topic.'],
     ['فقط خواندن کافی نیست؛ همان نوع سؤال را بارها حل کن، اشتباه را بنویس و یک قاعدهٔ کوتاه برای خودت بساز. برای Subnetting و محاسبه، تمرین روزانهٔ کوتاه بهتر از یک جلسهٔ طولانی است.', 'Nur Lesen reicht nicht: denselben Aufgabentyp mehrfach lösen, Fehler aufschreiben und eine kurze eigene Regel formulieren. Bei Subnetting und Rechnen helfen tägliche kurze Einheiten mehr als eine lange.', 'Reading isn’t enough: solve the same question type repeatedly, write down mistakes and form a short personal rule. For subnetting and calculations short daily sessions beat one long one.']],
    [['نمی‌دانی آلمانی سؤال را درست فهمیده‌ای یا نه.', 'Unsicher, ob du die deutsche Aufgabenstellung richtig verstehst.', 'Unsure whether you understand the German question correctly.'],
     ['فعل‌های سؤال را یاد بگیر: «nennen» فقط نام ببر، «beschreiben» توضیح بده، «erläutern» با دلیل یا مثال، «begründen» دلیل بیاور، «berechnen» راه حل و واحد. ابزار آزمون تمرینی همین برنامه را به آلمانی هم انجام بده.', 'Operatoren lernen: „nennen“ nur aufzählen, „beschreiben“ darstellen, „erläutern“ mit Grund oder Beispiel, „begründen“ Ursache angeben, „berechnen“ mit Rechenweg und Einheit. Das AP-Übungsquiz dieser App auch auf Deutsch machen.', 'Learn the task verbs: “nennen” list only, “beschreiben” describe, “erläutern” explain with reason or example, “begründen” justify, “berechnen” show working and units. Take this app’s AP quiz in German too.']]],
  decide: [
    [['وقت محدود (مثلاً کار تمام‌وقت)', 'Wenig Zeit (z. B. Vollzeitjob)', 'Little time (e.g. full-time job)'], ['اولویت: پروژه و ارائه (۵۰٪)، سپس شبکه و Subnetting، سپس WiSo (سؤال‌های تکراری و سریع‌الحفظ).', 'Priorität: Projekt und Präsentation (50 %), dann Netzwerk und Subnetting, dann WiSo (wiederkehrende, schnell lernbare Fragen).', 'Priority: project and presentation (50%), then networking and subnetting, then WiSo (recurring, quickly learnable questions).']],
    [['آزمون شفاهی تکمیلی پیشنهاد شده', 'Mündliche Ergänzungsprüfung angeboten', 'Oral supplementary exam offered'], ['اگر با آن می‌توانی قبول شوی، معمولاً ارزش دارد؛ همان مبحث را با سؤال‌های قدیمی و توضیح بلند تمرین کن.', 'Wenn sie das Bestehen ermöglicht, lohnt sie sich meist; genau dieses Gebiet mit Altfragen und lautem Erklären üben.', 'If it can make you pass, it’s usually worth it; practise that area with past questions and explaining aloud.']]],
  pitfalls: [
    ['دست‌کم گرفتن WiSo؛ ۱۰٪ است و با مطالعهٔ کم امتیاز آسان می‌دهد.', 'WiSo unterschätzen – 10 % mit wenig Aufwand leicht holbar.', 'Underestimating WiSo – 10% that is easy to earn with little effort.'],
    ['شروع دیر پروژه و مستندسازی.', 'Zu später Start von Projekt und Dokumentation.', 'Starting the project and documentation too late.'],
    ['فقط خواندن بدون حل آزمون زمان‌دار.', 'Nur lesen, keine zeitgestoppten Prüfungen.', 'Only reading, no timed exams.']],
  iv: [
    [['آزمون پایانی FISI چه بخش‌هایی دارد؟', 'Aus welchen Teilen besteht die FISI-Prüfung?', 'What parts does the FISI exam have?'], ['بخش ۱ کتبی ۲۰٪؛ بخش ۲ شامل پروژهٔ ۴۰ ساعته با ارائه و گفت‌وگوی تخصصی ۵۰٪، دو آزمون کتبی تخصصی هر کدام ۱۰٪ و WiSo ۱۰٪.', 'Teil 1 schriftlich 20 %; Teil 2 mit 40-Stunden-Projekt plus Präsentation und Fachgespräch 50 %, zwei schriftlichen Fachprüfungen je 10 % und WiSo 10 %.', 'Part 1 written 20%; part 2 with a 40-hour project plus presentation and discussion 50%, two technical written exams at 10% each and WiSo 10%.']],
    [['چطور برای آزمون آماده می‌شوی؟', 'Wie bereitest du dich auf die Prüfung vor?', 'How do you prepare for the exam?'], ['با برنامهٔ هفتگی، آزمون‌های قدیمی زمان‌دار، تحلیل اشتباه‌ها و تمرین روزانهٔ کوتاه برای محاسبه و Subnetting؛ پروژه را زود شروع و مرحله‌ای مستند می‌کنم.', 'Mit Wochenplan, zeitgestoppten Altprüfungen, Fehleranalyse und täglichen kurzen Rechen- und Subnettingübungen; das Projekt starte ich früh und dokumentiere laufend.', 'With a weekly plan, timed past exams, error analysis and short daily calculation and subnetting practice; I start the project early and document continuously.']],
    [['«erläutern» با «nennen» چه فرقی دارد؟', 'Unterschied zwischen „erläutern“ und „nennen“?', 'Difference between “erläutern” and “nennen”?'], ['nennen یعنی فقط نام بردن؛ erläutern یعنی توضیح با دلیل یا مثال، که امتیاز بیشتری دارد و پاسخ بلندتری می‌خواهد.', '„Nennen“ heißt nur aufzählen; „erläutern“ heißt mit Begründung oder Beispiel erklären – mehr Punkte, längere Antwort.', '“Nennen” means just list; “erläutern” means explain with reason or example – more points, longer answer.']]],
  sources: [['DIHK – Umsetzungshilfe IT-Berufe (Prüfungsstruktur)', 'https://www.ihk.de/blueprint/servlet/resource/blob/6945168/0424ce44eab4c49eab8b0c078fe7d796/dihk-umsetzungshilfe-it-berufe-data.pdf'], ['Verordnung FIAusbV (Gesetze im Internet)', 'https://www.gesetze-im-internet.de/fiausbv/'], ['AK Österreich / WKO – Lehrberuf Informationstechnologie', 'https://www.bic.at/']]
},

{
  id: 'ap-ap1', part: 1,
  title: ['بخش ۱: راه‌اندازی محل کار IT، مقایسهٔ پیشنهاد و نیاز حفاظتی', 'Teil 1: IT-Arbeitsplatz einrichten, Angebotsvergleich und Schutzbedarf', 'Part 1: setting up an IT workplace, offer comparison and protection needs'],
  goal: ['موضوعات رایج بخش ۱ را حل کنی: تحلیل نیاز مشتری، انتخاب سخت‌افزار با Nutzwertanalyse، مقایسهٔ پیشنهادها، تعیین نیاز حفاظتی (Schutzbedarf) و اقدامات امنیتی و نوشتن پاسخ کوتاه و دقیق.', 'Du löst typische Aufgaben aus Teil 1: Kundenbedarf analysieren, Hardware per Nutzwertanalyse auswählen, Angebote vergleichen, Schutzbedarf feststellen, Schutzmaßnahmen nennen und kurz und präzise antworten.', 'Solve typical part 1 tasks: analyse customer needs, choose hardware with a weighted scoring (Nutzwertanalyse), compare offers, determine protection needs and measures, and answer briefly and precisely.'],
  why: ['بخش ۱ یک‌پنجم نمرهٔ نهایی است و سناریوی آن دقیقاً کار روزانهٔ تکنسین است: «یک دفتر جدید با پنج محل کار آماده کن». همین مهارت‌ها در مصاحبه هم پرسیده می‌شوند.', 'Teil 1 macht ein Fünftel der Endnote aus, und sein Szenario ist Technikeralltag: „Richte ein neues Büro mit fünf Arbeitsplätzen ein“. Genau das fragen auch Bewerbungsgespräche ab.', 'Part 1 is a fifth of the final grade, and its scenario is everyday technician work: “set up a new office with five workstations”. Interviews ask exactly this too.'],
  know: [
    ['Nutzwertanalyse: معیارها (قیمت، کارایی، گارانتی، مصرف برق…) با وزن (جمع ۱۰۰٪)؛ هر گزینه برای هر معیار امتیاز (مثلاً ۱ تا ۱۰)؛ امتیاز × وزن جمع می‌شود و بیشترین جمع برنده است.', 'Nutzwertanalyse: Kriterien (Preis, Leistung, Garantie, Stromverbrauch …) mit Gewichtung (Summe 100 %); jede Alternative bekommt je Kriterium Punkte (z. B. 1–10); Punkte × Gewicht addieren, höchste Summe gewinnt.', 'Nutzwertanalyse: criteria (price, performance, warranty, power use …) with weights (summing to 100%); each option scores per criterion (e.g. 1–10); points × weight are summed and the highest total wins.'],
    ['مقایسهٔ پیشنهاد: قیمت خالص و ناخالص (مالیات بر ارزش افزوده ۱۹٪ در آلمان، ۲۰٪ در اتریش)، تخفیف (Rabatt)، تخفیف پرداخت زودهنگام (Skonto)، هزینهٔ ارسال؛ ترتیب محاسبه: قیمت فهرست − Rabatt + هزینه‌ها − Skonto.', 'Angebotsvergleich: Netto- und Bruttopreis (MwSt. 19 % in DE, 20 % in AT), Rabatt, Skonto, Versandkosten; Rechenweg: Listenpreis − Rabatt + Bezugskosten − Skonto (je nach Aufgabenstellung).', 'Offer comparison: net and gross price (VAT 19% in DE, 20% in AT), discount (Rabatt), early-payment discount (Skonto), shipping; order: list price − discount + costs − Skonto (as the task specifies).'],
    ['Schutzbedarf (BSI): برای محرمانگی، یکپارچگی و دسترس‌پذیری، سطح normal، hoch یا sehr hoch با دلیل؛ اقدام متناسب: رمزگذاری، پشتیبان، UPS، RAID، کنترل دسترسی.', 'Schutzbedarf (BSI): für Vertraulichkeit, Integrität und Verfügbarkeit jeweils normal, hoch oder sehr hoch mit Begründung; passende Maßnahmen: Verschlüsselung, Backup, USV, RAID, Zugriffskontrolle.', 'Protection needs (BSI): for confidentiality, integrity and availability each normal, high or very high with a reason; matching measures: encryption, backup, UPS, RAID, access control.'],
    ['محل کار: الزامات ارگونومی و ایمنی (Bildschirmarbeitsplatz)، اتصال شبکه (LAN، WLAN، VLAN)، تصویر سیستم و Deployment، DSGVO هنگام مستقر کردن دستگاه، و تحویل به کاربر با پروتکل.', 'Arbeitsplatz: Ergonomie- und Sicherheitsanforderungen (Bildschirmarbeitsplatz), Netzanbindung (LAN, WLAN, VLAN), Installation und Verteilung, DSGVO bei der Einrichtung und Übergabe an den Benutzer mit Übergabeprotokoll.', 'Workstation: ergonomics and safety requirements (display screen work), network connection (LAN, WLAN, VLAN), installation and deployment, GDPR during setup and handover to the user with a handover record.'],
    ['ارتباط با مشتری: نیاز را با پرسش باز روشن کن، فرق «الزام» و «آرزو»، و پیشنهاد را با دلیل مستند کن. در پاسخ آزمون، فهرست کوتاه با دلیل بهتر از متن بلند است.', 'Kundenkommunikation: Bedarf mit offenen Fragen klären, Muss- von Kann-Anforderungen trennen, Empfehlung begründen. In der Prüfung sind kurze Stichpunkte mit Begründung besser als lange Texte.', 'Customer communication: clarify needs with open questions, separate must-haves from nice-to-haves, justify recommendations. In the exam short bullet points with reasons beat long texts.']],
  lab: { vm: 'Papier oder Tabelle', shell: 'Rechenweg',
    steps: [
      ['سناریو را بخوان: دفتر وکالت با ۵ کارمند، نیاز به ۵ لپ‌تاپ.', 'برای سه پیشنهاد لپ‌تاپ Nutzwertanalyse با وزن‌های داده‌شده حساب کن.', 'قیمت نهایی پیشنهاد B را با Rabatt، هزینهٔ ارسال و Skonto حساب کن.', 'نیاز حفاظتی دادهٔ موکلان را برای C، I و A تعیین و دلیل بیاور؛ سه اقدام مناسب بنویس.', 'پاسخ‌هایت را با حل نمونه مقایسه کن.'],
      ['Szenario lesen: Anwaltskanzlei mit 5 Beschäftigten braucht 5 Notebooks.', 'Für drei Notebook-Angebote die Nutzwertanalyse mit den gegebenen Gewichten rechnen.', 'Den Endpreis von Angebot B mit Rabatt, Versand und Skonto berechnen.', 'Schutzbedarf der Mandantendaten für V, I und V(erfügbarkeit) mit Begründung bestimmen; drei passende Maßnahmen nennen.', 'Mit der Musterlösung vergleichen.'],
      ['Read the scenario: a law office with 5 staff needs 5 laptops.', 'Compute the weighted scoring for three laptop offers with the given weights.', 'Compute offer B’s final price with discount, shipping and Skonto.', 'Determine protection needs of client data for C, I and A with reasons; name three suitable measures.', 'Compare with the sample solution.']],
    code: 'Nutzwertanalyse (Punkte 1–10)\nKriterium      Gewicht   A    B    C\nPreis           40 %     6    8    5\nLeistung        25 %     8    7    9\nGarantie        20 %     5    8    7\nAkkulaufzeit    15 %     7    6    8\nLösung: A = 0,4·6+0,25·8+0,2·5+0,15·7 = 2,4+2,0+1,0+1,05 = 6,45\n        B = 3,2+1,75+1,6+0,9 = 7,45   C = 2,0+2,25+1,4+1,2 = 6,85   -> Angebot B\n\nAngebot B: Listenpreis 1.150,00 € netto je Gerät, 5 Stück, 8 % Rabatt, Versand 25,00 €, 2 % Skonto\n  5 × 1.150,00            = 5.750,00 €\n  − 8 % Rabatt (460,00)   = 5.290,00 €\n  + Versand               = 5.315,00 €\n  − 2 % Skonto (106,30)   = 5.208,70 € netto\n  + 19 % MwSt. (989,65)   = 6.198,35 € brutto (DE)\n\nSchutzbedarf Mandantendaten\nVertraulichkeit sehr hoch (Berufsgeheimnis, DSGVO Art. 9-nahe Daten, Haftung)\nIntegrität hoch (falsche Akten führen zu Fehlentscheidungen)\nVerfügbarkeit hoch (Fristen dürfen nicht verpasst werden)\nMaßnahmen: BitLocker-Vollverschlüsselung, MFA, tägliches Backup mit Offline-Kopie, Zugriff nur nach Mandat',
    checks: [
      ['Nutzwertanalyse را درست حساب کردی (B با ۷٫۴۵).', 'قیمت خالص ۵٬۲۰۸٫۷۰ یورو و ناخالص آلمان ۶٬۱۹۸٫۳۵ یورو به دست آمد.', 'برای هر سه هدف حفاظتی سطح و دلیل نوشتی.', 'سه اقدام متناسب با نیاز حفاظتی نام بردی.'],
      ['Nutzwertanalyse richtig (B mit 7,45).', 'Nettopreis 5.208,70 € und Bruttopreis DE 6.198,35 € erhalten.', 'Für alle drei Schutzziele Stufe und Begründung notiert.', 'Drei zum Schutzbedarf passende Maßnahmen genannt.'],
      ['Weighted scoring correct (B at 7.45).', 'Net €5,208.70 and German gross €6,198.35 obtained.', 'Level and reason noted for all three protection goals.', 'Three measures matching the protection needs named.']] },
  trouble: [
    [['در Nutzwertanalyse جمع وزن‌ها ۱۰۰٪ نمی‌شود.', 'In der Nutzwertanalyse ergeben die Gewichte nicht 100 %.', 'In the scoring the weights don’t sum to 100%.'],
     ['اول جمع وزن‌ها را کنترل کن؛ اگر سؤال اشتباه دارد، فرض خودت را صریح بنویس. وزن‌ها را اعشاری (۰٫۴) بنویس تا اشتباه محاسبه کم شود و برای هر گزینه جدا جمع بزن.', 'Zuerst die Gewichtssumme prüfen; ist die Aufgabe fehlerhaft, die eigene Annahme ausdrücklich notieren. Gewichte als Dezimalzahl (0,4) schreiben und je Alternative getrennt summieren.', 'Check the weight sum first; if the task is flawed, state your assumption explicitly. Write weights as decimals (0.4) and sum each option separately.']],
    [['ترتیب Rabatt و Skonto را قاطی می‌کنی.', 'Reihenfolge von Rabatt und Skonto verwechselt.', 'Mixing up the order of discount and Skonto.'],
     ['Rabatt روی قیمت فهرست، سپس هزینهٔ ارسال، Skonto در آخر (چون برای پرداخت سریع فاکتور است)، و مالیات روی مبلغ نهایی خالص. همیشه راه حل و واحد (€) را بنویس.', 'Rabatt auf den Listenpreis, dann Bezugskosten, Skonto zuletzt (Zahlungsvorteil auf die Rechnung), MwSt. auf den Nettoendbetrag. Immer Rechenweg und Einheit (€) angeben.', 'Discount on list price, then shipping, Skonto last (a payment benefit on the invoice), VAT on the final net. Always show working and units (€).']],
    [['نمی‌دانی نیاز حفاظتی را hoch بگذاری یا sehr hoch.', 'Unsicher, ob der Schutzbedarf hoch oder sehr hoch ist.', 'Unsure whether protection need is high or very high.'],
     ['معیار، اثر خسارت است: خسارت محدود و قابل‌جبران = normal، قابل‌توجه = hoch، تهدید وجود شرکت یا آسیب جدی به افراد = sehr hoch. مهم‌تر از خود سطح، دلیل منطقی است.', 'Maßstab ist das Schadensausmaß: begrenzt und überschaubar = normal, beträchtlich = hoch, existenzbedrohend oder schwere Folgen für Personen = sehr hoch. Wichtiger als die Stufe ist eine schlüssige Begründung.', 'The measure is impact: limited and manageable = normal, considerable = high, threatening the company’s existence or serious harm to people = very high. A sound reason matters more than the level.']]],
  decide: [
    [['مشتری فقط قیمت را مهم می‌داند', 'Kunde achtet nur auf den Preis', 'Customer only cares about price'], ['با Nutzwertanalyse نشان بده هزینهٔ کل (گارانتی، برق، پشتیبانی) چه می‌گوید؛ تصمیم با مشتری است ولی مستند.', 'Mit Nutzwertanalyse zeigen, was die Gesamtkosten (Garantie, Strom, Support) sagen; die Entscheidung trifft der Kunde – dokumentiert.', 'Use the weighted scoring to show what total cost (warranty, power, support) says; the customer decides – documented.']],
    [['دادهٔ بسیار حساس روی دستگاه‌های قابل‌حمل', 'Sehr sensible Daten auf mobilen Geräten', 'Very sensitive data on mobile devices'], ['رمزگذاری کامل دیسک، MFA، مدیریت دستگاه (Intune)، و قفل از راه دور الزامی.', 'Vollverschlüsselung, MFA, Geräteverwaltung (Intune) und Fernlöschung sind Pflicht.', 'Full disk encryption, MFA, device management (Intune) and remote wipe are mandatory.']]],
  pitfalls: [
    ['جواب عددی بدون راه حل و واحد.', 'Zahlenergebnis ohne Rechenweg und Einheit.', 'A numeric answer without working and units.'],
    ['تعیین نیاز حفاظتی بدون دلیل.', 'Schutzbedarf ohne Begründung.', 'Protection needs without reasons.'],
    ['نوشتن متن بلند وقتی «nennen» خواسته شده.', 'Lange Texte, obwohl „nennen“ gefragt ist.', 'Writing long text when “nennen” is asked.']],
  iv: [
    [['Nutzwertanalyse چیست؟', 'Was ist eine Nutzwertanalyse?', 'What is a Nutzwertanalyse?'], ['روش تصمیم‌گیری با معیارهای وزن‌دار؛ برای هر گزینه امتیاز × وزن جمع می‌شود تا گزینهٔ بهتر به‌صورت قابل‌ردیابی انتخاب شود.', 'Ein Entscheidungsverfahren mit gewichteten Kriterien; je Alternative werden Punkte × Gewicht summiert, damit die Wahl nachvollziehbar wird.', 'A decision method with weighted criteria; per option points × weight are summed so the choice is traceable.']],
    [['سه هدف حفاظتی اطلاعات کدام‌اند؟', 'Welche drei Schutzziele gibt es?', 'What are the three protection goals?'], ['محرمانگی (Vertraulichkeit)، یکپارچگی (Integrität)، دسترس‌پذیری (Verfügbarkeit).', 'Vertraulichkeit, Integrität, Verfügbarkeit.', 'Confidentiality, integrity, availability.']],
    [['فرق Rabatt و Skonto؟', 'Unterschied Rabatt und Skonto?', 'Rabatt vs Skonto?'], ['Rabatt کاهش قیمت (مثلاً برای مقدار یا مشتری خاص) است؛ Skonto کاهش برای پرداخت سریع در مهلت مشخص.', 'Rabatt ist ein Preisnachlass (z. B. Mengen- oder Kundenrabatt); Skonto ein Nachlass für Zahlung innerhalb einer Frist.', 'Rabatt is a price reduction (e.g. volume or customer); Skonto is a reduction for paying within a deadline.']]],
  sources: [['BSI – IT-Grundschutz (Schutzbedarfsfeststellung, BSI-Standard 200-2)', 'https://www.bsi.bund.de/standards'], ['DIHK – Umsetzungshilfe IT-Berufe', 'https://www.ihk.de/blueprint/servlet/resource/blob/6945168/0424ce44eab4c49eab8b0c078fe7d796/dihk-umsetzungshilfe-it-berufe-data.pdf'], ['BAuA – Bildschirmarbeit', 'https://www.baua.de/']]
},

{
  id: 'ap-rechnen', part: 2,
  title: ['محاسبه‌های آزمون: انتقال داده، حافظه، برق، UPS و هزینه', 'Rechenaufgaben: Übertragung, Speicher, Strom, USV und Kosten', 'Exam calculations: transfer, storage, power, UPS and cost'],
  goal: ['انواع رایج محاسبهٔ آزمون را با راه حل کامل و واحد درست انجام دهی: زمان انتقال، حجم تصویر و ویدئو، ظرفیت RAID، هزینهٔ برق، اندازهٔ UPS، استهلاک و زمان بازگشت سرمایه.', 'Du löst typische Rechenaufgaben mit vollständigem Rechenweg und richtigen Einheiten: Übertragungszeit, Bild- und Videogröße, RAID-Kapazität, Stromkosten, USV-Dimensionierung, Abschreibung und Amortisation.', 'Solve typical exam calculations with full working and correct units: transfer time, image and video size, RAID capacity, power cost, UPS sizing, depreciation and payback.'],
  why: ['تقریباً در هر آزمون کتبی چند سؤال محاسبه هست و امتیاز آن با تمرین کم، تقریباً تضمین‌شده است. در کار هم باید زمان پشتیبان‌گیری، ظرفیت دیسک یا هزینهٔ برق اتاق سرور را تخمین بزنی.', 'In fast jeder schriftlichen Prüfung gibt es Rechenaufgaben, deren Punkte mit wenig Übung fast sicher sind. Im Job schätzt man Backupzeiten, Plattenkapazität oder Stromkosten des Serverraums.', 'Nearly every written exam has calculations whose points are almost guaranteed with little practice. At work you estimate backup times, disk capacity or server room power cost.'],
  know: [
    ['واحدها: ۱ بایت = ۸ بیت. پیشوند ده‌دهی: 1 kB = 1000 B، 1 MB = 10^6 B؛ دودویی: 1 KiB = 1024 B، 1 MiB = 1024² B، 1 GiB = 1024³ B. سرعت شبکه همیشه بیت بر ثانیه و ده‌دهی است (100 Mbit/s = 100 000 000 bit/s).', 'Einheiten: 1 Byte = 8 Bit. Dezimal: 1 kB = 1000 B, 1 MB = 10^6 B; binär: 1 KiB = 1024 B, 1 MiB = 1024² B, 1 GiB = 1024³ B. Netzwerkraten sind immer Bit pro Sekunde und dezimal (100 Mbit/s = 100 000 000 bit/s).', 'Units: 1 byte = 8 bits. Decimal: 1 kB = 1000 B, 1 MB = 10^6 B; binary: 1 KiB = 1024 B, 1 MiB = 1024² B, 1 GiB = 1024³ B. Network rates are always bits per second and decimal (100 Mbit/s = 100,000,000 bit/s).'],
    ['زمان انتقال = حجم داده (بیت) ÷ نرخ داده (bit/s). تصویر بی‌فشرده = عرض × ارتفاع × عمق رنگ (bit). ویدئو = تصویر × فریم بر ثانیه × ثانیه.', 'Übertragungszeit = Datenmenge (Bit) ÷ Datenrate (bit/s). Unkomprimiertes Bild = Breite × Höhe × Farbtiefe (Bit). Video = Bild × Bilder pro Sekunde × Sekunden.', 'Transfer time = data size (bits) ÷ data rate (bit/s). Uncompressed image = width × height × colour depth (bits). Video = image × frames per second × seconds.'],
    ['برق: انرژی (kWh) = توان (W) × ساعت ÷ 1000؛ هزینه = kWh × قیمت هر kWh. UPS: توان ظاهری (VA) = توان واقعی (W) ÷ cos φ؛ UPS باید هم W و هم VA کافی با ذخیره داشته باشد.', 'Strom: Energie (kWh) = Leistung (W) × Stunden ÷ 1000; Kosten = kWh × Preis pro kWh. USV: Scheinleistung (VA) = Wirkleistung (W) ÷ cos φ; die USV muss W und VA mit Reserve abdecken.', 'Power: energy (kWh) = power (W) × hours ÷ 1000; cost = kWh × price per kWh. UPS: apparent power (VA) = real power (W) ÷ cos φ; the UPS must cover both W and VA with headroom.'],
    ['RAID: 0 = n، 1 = n/2، 5 = n−1، 6 = n−2، 10 = n/2 (n = تعداد دیسک‌ها با اندازهٔ برابر).', 'RAID: 0 = n, 1 = n/2, 5 = n−1, 6 = n−2, 10 = n/2 (n = Anzahl gleich großer Platten).', 'RAID: 0 = n, 1 = n/2, 5 = n−1, 6 = n−2, 10 = n/2 (n = number of equal disks).'],
    ['استهلاک خطی: هزینهٔ خرید ÷ عمر مفید = مبلغ سالانه. زمان بازگشت سرمایه (Amortisation) = سرمایه‌گذاری ÷ صرفه‌جویی در هر دوره.', 'Lineare Abschreibung: Anschaffungskosten ÷ Nutzungsdauer = Jahresbetrag. Amortisationszeit = Investition ÷ Ersparnis je Periode.', 'Straight-line depreciation: purchase cost ÷ useful life = yearly amount. Payback time = investment ÷ saving per period.']],
  lab: { vm: 'Papier und Taschenrechner', shell: 'Rechenweg',
    steps: [
      ['زمان انتقال ۲٫۵ GiB روی 100 Mbit/s را حساب کن.', 'حجم یک عکس 6000×4000 با ۲۴ بیت رنگ را به MB و MiB حساب کن.', 'هزینهٔ سالانهٔ برق یک سرور ۳۵۰ واتی ۲۴/۷ با قیمت ۰٫۳۰ یورو بر kWh را حساب کن.', 'UPS لازم برای بار ۱۲۰۰ وات با cos φ = 0٫8 و ۲۵٪ ذخیره را تعیین کن.', 'زمان بازگشت سرمایهٔ یک سرور ۶٬۰۰۰ یورویی که ماهانه ۲۵۰ یورو صرفه‌جویی می‌آورد و ظرفیت RAID 5 با ۴ دیسک ۴TB را حساب کن.'],
      ['Übertragungszeit für 2,5 GiB bei 100 Mbit/s berechnen.', 'Größe eines Fotos 6000×4000 mit 24 Bit Farbtiefe in MB und MiB berechnen.', 'Jährliche Stromkosten eines 350-W-Servers im 24/7-Betrieb bei 0,30 €/kWh berechnen.', 'Benötigte USV für 1200 W Last bei cos φ = 0,8 und 25 % Reserve bestimmen.', 'Amortisation eines 6.000-€-Servers mit 250 € Ersparnis pro Monat und Kapazität von RAID 5 mit 4 × 4 TB berechnen.'],
      ['Compute the transfer time for 2.5 GiB at 100 Mbit/s.', 'Compute the size of a 6000×4000 photo at 24-bit colour in MB and MiB.', 'Compute yearly power cost of a 350 W server running 24/7 at €0.30/kWh.', 'Size a UPS for a 1200 W load at cos φ = 0.8 with 25% headroom.', 'Compute payback of a €6,000 server saving €250 a month and the capacity of RAID 5 with 4 × 4 TB.']],
    code: '1) Übertragung\n   2,5 GiB = 2,5 × 1024³ B = 2.684.354.560 B × 8 = 21.474.836.480 bit\n   t = 21.474.836.480 bit ÷ 100.000.000 bit/s ≈ 214,7 s ≈ 3 min 35 s (ohne Protokoll-Overhead)\n\n2) Bildgröße\n   6000 × 4000 × 24 bit = 576.000.000 bit ÷ 8 = 72.000.000 B = 72 MB\n   72.000.000 B ÷ 1024² ≈ 68,66 MiB\n\n3) Stromkosten\n   350 W × 24 h × 365 = 3.066.000 Wh = 3.066 kWh\n   3.066 kWh × 0,30 €/kWh = 919,80 € pro Jahr\n\n4) USV\n   Scheinleistung = 1200 W ÷ 0,8 = 1500 VA; mit 25 % Reserve: 1875 VA und 1500 W\n   -> USV mit mindestens 1875 VA und 1500 W Wirkleistung wählen (z. B. 2000 VA / 1800 W)\n\n5) Amortisation und RAID\n   6.000 € ÷ 250 €/Monat = 24 Monate\n   RAID 5: (4 − 1) × 4 TB = 12 TB nutzbar (1 Platte darf ausfallen)',
    checks: [
      ['زمان انتقال را حدود ۲۱۵ ثانیه به دست آوردی و فرق GiB و GB را رعایت کردی.', 'حجم عکس ۷۲ MB و حدود ۶۸٫۷ MiB شد.', 'هزینهٔ برق ۹۱۹٫۸۰ یورو در سال شد.', 'UPS با حداقل ۱۸۷۵ VA و ۱۵۰۰ W، بازگشت سرمایهٔ ۲۴ ماه و RAID 5 برابر ۱۲ TB.'],
      ['Übertragungszeit etwa 215 s, Unterschied GiB/GB beachtet.', 'Fotogröße 72 MB bzw. etwa 68,7 MiB.', 'Stromkosten 919,80 € pro Jahr.', 'USV mindestens 1875 VA und 1500 W, Amortisation 24 Monate, RAID 5 mit 12 TB.'],
      ['Transfer time about 215 s, GiB vs GB respected.', 'Photo size 72 MB or about 68.7 MiB.', 'Power cost €919.80 per year.', 'UPS at least 1875 VA and 1500 W, payback 24 months, RAID 5 at 12 TB.']] },
  trouble: [
    [['جواب انتقال داده ۸ برابر اشتباه است.', 'Das Übertragungsergebnis ist um Faktor 8 falsch.', 'The transfer result is off by a factor of 8.'],
     ['بایت و بیت را قاطی کرده‌ای: حجم فایل معمولاً بایت است و سرعت شبکه بیت. قبل از تقسیم، هر دو را به بیت ببر.', 'Byte und Bit verwechselt: Dateigrößen sind meist in Byte, Netzraten in Bit. Vor dem Teilen beides in Bit umrechnen.', 'Bytes and bits mixed up: file sizes are usually bytes, network rates bits. Convert both to bits before dividing.']],
    [['نمی‌دانی ۱۰۲۴ یا ۱۰۰۰.', 'Unsicher: 1024 oder 1000?', 'Unsure: 1024 or 1000?'],
     ['به پیشوند نگاه کن: KiB/MiB/GiB یعنی ۱۰۲۴، kB/MB/GB یعنی ۱۰۰۰ (در آزمون معمولاً روشن گفته می‌شود). اگر مبهم بود، فرضت را بنویس. سرعت شبکه همیشه ۱۰۰۰.', 'Auf das Präfix achten: KiB/MiB/GiB = 1024, kB/MB/GB = 1000 (in der Prüfung meist klar angegeben). Ist es unklar, Annahme notieren. Netzraten sind immer 1000.', 'Look at the prefix: KiB/MiB/GiB = 1024, kB/MB/GB = 1000 (usually explicit in exams). If ambiguous, state your assumption. Network rates are always 1000.']],
    [['در محاسبهٔ UPS فقط وات یا فقط VA را در نظر گرفته‌ای.', 'Bei der USV nur Watt oder nur VA beachtet.', 'For the UPS you considered only watts or only VA.'],
     ['UPS دو محدودیت دارد؛ بار باید زیر هر دو باشد. با cos φ از W به VA برو، ذخیره را اضافه کن و مدلی انتخاب کن که هر دو عدد را پوشش دهد. زمان پشتیبانی (Autonomie) را هم از جدول سازنده بخوان.', 'Eine USV hat zwei Grenzen; die Last muss unter beiden liegen. Mit cos φ von W nach VA umrechnen, Reserve aufschlagen und ein Modell wählen, das beide Werte abdeckt. Die Überbrückungszeit aus der Herstellertabelle lesen.', 'A UPS has two limits; the load must be below both. Convert W to VA with cos φ, add headroom and choose a model covering both. Read runtime from the vendor table.']]],
  decide: [
    [['پشتیبان شبانه از ۵۰۰ GB روی 1 Gbit/s', 'Nächtliches Backup von 500 GB über 1 Gbit/s', 'Nightly backup of 500 GB over 1 Gbit/s'], ['حدود ۴۰۰۰ ثانیه (~۶۷ دقیقه) بدون سربار؛ با ۷۰٪ بهره‌وری واقعی حدود ۹۵ دقیقه – در پنجرهٔ شب جا می‌شود؛ پشتیبان افزایشی بسیار کوتاه‌تر است.', 'Rund 4000 s (~67 Min.) ohne Overhead; bei realistisch 70 % Auslastung etwa 95 Min. – passt ins Nachtfenster; inkrementelle Sicherungen sind deutlich kürzer.', 'About 4000 s (~67 min) without overhead; at a realistic 70% efficiency about 95 min – fits the night window; incrementals are much shorter.']],
    [['انتخاب بین RAID 5 و RAID 10 با ۴ دیسک ۴TB', 'Wahl zwischen RAID 5 und RAID 10 mit 4 × 4 TB', 'Choosing RAID 5 vs RAID 10 with 4 × 4 TB'], ['RAID 5 = ۱۲ TB، RAID 10 = ۸ TB ولی سریع‌تر و با Rebuild امن‌تر؛ برای پایگاه داده RAID 10، برای آرشیو RAID 6 با ۵ دیسک یا بیشتر.', 'RAID 5 = 12 TB, RAID 10 = 8 TB, aber schneller und sicherer im Rebuild; für Datenbanken RAID 10, fürs Archiv RAID 6 ab 5 Platten.', 'RAID 5 = 12 TB, RAID 10 = 8 TB but faster with a safer rebuild; RAID 10 for databases, RAID 6 with 5+ disks for archives.']]],
  pitfalls: [
    ['فراموش کردن ضرب در ۸ (بایت → بیت).', 'Das × 8 (Byte → Bit) vergessen.', 'Forgetting × 8 (bytes → bits).'],
    ['نتیجه بدون واحد یا با واحد اشتباه.', 'Ergebnis ohne oder mit falscher Einheit.', 'A result without or with the wrong unit.'],
    ['گرد کردن زودهنگام وسط محاسبه.', 'Zu frühes Runden mitten in der Rechnung.', 'Rounding too early mid-calculation.']],
  iv: [
    [['فرق MB و MiB؟', 'Unterschied MB und MiB?', 'MB vs MiB?'], ['MB ده‌دهی است (۱٬۰۰۰٬۰۰۰ بایت) و MiB دودویی (۱٬۰۴۸٬۵۷۶ بایت)؛ برای همین دیسک ۱ TB در ویندوز حدود ۹۳۱ GiB نشان داده می‌شود.', 'MB ist dezimal (1.000.000 Byte), MiB binär (1.048.576 Byte) – deshalb zeigt Windows eine 1-TB-Platte als etwa 931 GiB.', 'MB is decimal (1,000,000 bytes), MiB binary (1,048,576 bytes) – which is why Windows shows a 1 TB disk as about 931 GiB.']],
    [['چرا UPS هم VA دارد هم W؟', 'Warum hat eine USV VA und W?', 'Why does a UPS have VA and W ratings?'], ['چون توان ظاهری (VA) و توان واقعی (W) با ضریب توان (cos φ) فرق دارند؛ بار باید زیر هر دو محدودیت باشد.', 'Weil Schein- (VA) und Wirkleistung (W) über den Leistungsfaktor (cos φ) verschieden sind; die Last muss unter beiden Grenzen bleiben.', 'Apparent (VA) and real (W) power differ by the power factor (cos φ); the load must stay below both limits.']],
    [['هزینهٔ برق یک سرور را چطور حساب می‌کنی؟', 'Wie berechnest du die Stromkosten eines Servers?', 'How do you calculate a server’s power cost?'], ['توان متوسط (W) × ساعت‌های کار ÷ 1000 = kWh، ضربدر قیمت هر kWh؛ برای دقت، توان واقعی اندازه‌گیری‌شده نه برچسب منبع تغذیه.', 'Durchschnittsleistung (W) × Betriebsstunden ÷ 1000 = kWh, mal Preis pro kWh – genauer mit gemessener Leistung statt Netzteilangabe.', 'Average power (W) × operating hours ÷ 1000 = kWh, times price per kWh – more precise with measured power instead of the PSU label.']]],
  sources: [['IEC binary prefixes (NIST)', 'https://physics.nist.gov/cuu/Units/binary.html'], ['DIHK – Umsetzungshilfe IT-Berufe', 'https://www.ihk.de/blueprint/servlet/resource/blob/6945168/0424ce44eab4c49eab8b0c078fe7d796/dihk-umsetzungshilfe-it-berufe-data.pdf'], ['Subnetting-Trainer in dieser App', 'https://arefi2027.github.io/arefi-itpraxis/#subnetz']]
},

{
  id: 'ap-wiso', part: 2,
  title: ['WiSo: آموزش حرفه‌ای، قرارداد کار، بیمهٔ اجتماعی و شکل‌های حقوقی شرکت', 'WiSo: Ausbildung, Arbeitsrecht, Sozialversicherung und Rechtsformen', 'WiSo: vocational training, labour law, social insurance and company forms'],
  goal: ['موضوعات پرتکرار WiSo را با پاسخ مطمئن بدانی: حقوق و وظایف در آموزش (BBiG)، قرارداد و فسخ کار، پنج شاخهٔ بیمهٔ اجتماعی، شورای کارکنان، قرارداد جمعی و شکل‌های حقوقی شرکت.', 'Du beherrschst die häufigsten WiSo-Themen: Rechte und Pflichten in der Ausbildung (BBiG), Arbeitsvertrag und Kündigung, die fünf Zweige der Sozialversicherung, Betriebsrat, Tarifvertrag und Rechtsformen.', 'Master the most frequent WiSo topics: rights and duties in training (BBiG), employment contracts and termination, the five social insurance branches, works council, collective agreements and company legal forms.'],
  why: ['WiSo ۱۰٪ نمره است، چندگزینه‌ای و تکراری؛ با چند ساعت مطالعهٔ هدفمند امتیاز تقریباً قطعی است. همین دانش در زندگی کاری در آلمان (قرارداد، فیش حقوقی، فسخ) هم به کارت می‌آید.', 'WiSo bringt 10 %, ist gebunden und wiederholt sich – mit wenigen Stunden gezieltem Lernen fast sichere Punkte. Das Wissen hilft auch im Arbeitsleben in Deutschland (Vertrag, Lohnabrechnung, Kündigung).', 'WiSo is 10%, multiple choice and repetitive – nearly guaranteed points with a few hours of focused study. The knowledge also helps in German working life (contracts, payslips, termination).'],
  know: [
    ['BBiG (قانون آموزش حرفه‌ای): قرارداد آموزش کتبی، دورهٔ آزمایشی ۱ تا ۴ ماه (در آن فسخ بدون مهلت ممکن است)، بعد از آن کارآموز با ۴ هفته مهلت فقط برای ترک حرفه یا تغییر رشته؛ کارفرما فقط با دلیل مهم. حق حقوق آموزش و گواهی کار دارد.', 'BBiG: schriftlicher Ausbildungsvertrag, Probezeit 1–4 Monate (fristlose Kündigung möglich), danach kann der Azubi nur bei Berufsaufgabe oder -wechsel mit 4 Wochen Frist kündigen, der Betrieb nur aus wichtigem Grund. Anspruch auf Vergütung und Zeugnis.', 'BBiG: written training contract, probation 1–4 months (termination without notice possible); afterwards the trainee may quit only to give up or change the occupation with 4 weeks’ notice, the employer only for good cause. Right to pay and a reference.'],
    ['قرارداد کار: مهلت قانونی فسخ پایه ۴ هفته تا پانزدهم یا پایان ماه (§ 622 BGB) و با سابقهٔ طولانی‌تر برای کارفرما بیشتر. فسخ همیشه کتبی. در شرکت‌های بیش از ۱۰ کارمند قانون حمایت از فسخ (KSchG) بعد از ۶ ماه.', 'Arbeitsvertrag: gesetzliche Grundkündigungsfrist 4 Wochen zum 15. oder Monatsende (§ 622 BGB), für den Arbeitgeber mit längerer Betriebszugehörigkeit länger. Kündigung immer schriftlich. In Betrieben mit mehr als 10 Beschäftigten gilt nach 6 Monaten das Kündigungsschutzgesetz.', 'Employment contract: statutory basic notice 4 weeks to the 15th or end of month (§ 622 BGB), longer for the employer with longer service. Termination always in writing. In businesses with more than 10 employees the Protection Against Dismissal Act applies after 6 months.'],
    ['پنج شاخهٔ بیمهٔ اجتماعی: درمان، مراقبت، بازنشستگی، بیکاری (تقریباً نصف‌نصف کارگر و کارفرما) و حوادث کار (فقط کارفرما، از طریق Berufsgenossenschaft).', 'Fünf Zweige der Sozialversicherung: Kranken-, Pflege-, Renten-, Arbeitslosenversicherung (etwa hälftig Arbeitnehmer und Arbeitgeber) und Unfallversicherung (nur Arbeitgeber, über die Berufsgenossenschaft).', 'Five social insurance branches: health, long-term care, pension, unemployment (roughly split between employee and employer) and accident insurance (employer only, via the Berufsgenossenschaft).'],
    ['مشارکت: شورای کارکنان (Betriebsrat) از ۵ کارمند دائمی دارای حق رأی ممکن است؛ نمایندگی جوانان و کارآموزان (JAV)؛ قرارداد جمعی (Tarifvertrag) بین اتحادیه و انجمن کارفرمایان؛ آزادی ائتلاف در قانون اساسی (Art. 9 GG).', 'Mitbestimmung: Betriebsrat ab 5 ständigen wahlberechtigten Beschäftigten möglich; Jugend- und Auszubildendenvertretung (JAV); Tarifvertrag zwischen Gewerkschaft und Arbeitgeberverband; Koalitionsfreiheit im Grundgesetz (Art. 9 GG).', 'Co-determination: a works council is possible from 5 permanent eligible employees; youth and trainee representation (JAV); collective agreements between union and employer association; freedom of association in the Basic Law (Art. 9 GG).'],
    ['شکل‌های حقوقی: GbR، OHG و KG (شرکای پاسخ‌گو با کل دارایی شخصی؛ در KG، Kommanditist فقط تا سهم خودش)، GmbH با حداقل سرمایهٔ ۲۵٬۰۰۰ یورو، UG از ۱ یورو، AG با ۵۰٬۰۰۰ یورو. ارگان‌های GmbH: Geschäftsführer و مجمع شرکا.', 'Rechtsformen: GbR, OHG und KG (Gesellschafter haften mit dem Privatvermögen; in der KG haftet der Kommanditist nur mit seiner Einlage), GmbH mit mindestens 25.000 € Stammkapital, UG ab 1 €, AG mit 50.000 € Grundkapital. Organe der GmbH: Geschäftsführer und Gesellschafterversammlung.', 'Legal forms: GbR, OHG and KG (partners liable with private assets; in a KG the limited partner only up to the contribution), GmbH with at least €25,000 share capital, UG from €1, AG with €50,000. GmbH bodies: managing director and shareholders’ meeting.'],
    ['حمایت از جوانان (JArbSchG برای زیر ۱۸ سال): حداکثر ۸ ساعت در روز و ۴۰ ساعت در هفته، معمولاً ۵ روز کاری، استراحت و محدودیت کار شبانه.', 'Jugendarbeitsschutz (JArbSchG, unter 18): höchstens 8 Stunden täglich und 40 Stunden wöchentlich, in der Regel 5-Tage-Woche, Pausen und Nachtarbeitsverbot.', 'Youth protection (JArbSchG, under 18): max 8 hours a day and 40 a week, usually a 5-day week, breaks and night work limits.']],
  lab: { vm: 'AP-Übungsquiz (Kategorie WiSo) + Notizen', shell: 'Lernkarten',
    steps: [
      ['آزمون تمرینی AP این برنامه را با دستهٔ WiSo اجرا کن و امتیاز اول را یادداشت کن.', 'برای هر پاسخ اشتباه، یک کارت یادگیری (پرسش در یک طرف، پاسخ و دلیل در طرف دیگر) بنویس.', 'جدول پنج بیمهٔ اجتماعی با پرداخت‌کننده و نهاد مسئول را از حفظ بنویس.', 'جدول شکل‌های حقوقی (مسئولیت، حداقل سرمایه، ارگان‌ها) را از حفظ بنویس.', 'آزمون را تا رسیدن به ۹۰٪ تکرار کن.'],
      ['AP-Übungsquiz dieser App mit Kategorie WiSo starten und ersten Punktestand notieren.', 'Zu jeder falschen Antwort eine Lernkarte schreiben (Frage vorne, Antwort und Begründung hinten).', 'Tabelle der fünf Sozialversicherungen mit Beitragszahler und Träger aus dem Kopf schreiben.', 'Tabelle der Rechtsformen (Haftung, Mindestkapital, Organe) aus dem Kopf schreiben.', 'Quiz wiederholen, bis 90 % erreicht sind.'],
      ['Run this app’s AP practice quiz with category WiSo and note your first score.', 'Write a flashcard for each wrong answer (question on front, answer and reason on back).', 'Write the table of the five social insurances with payer and institution from memory.', 'Write the legal forms table (liability, minimum capital, bodies) from memory.', 'Repeat the quiz until you reach 90%.']],
    code: 'Sozialversicherung        Beitrag                         Träger\nKrankenversicherung       AN und AG (etwa hälftig)        Krankenkassen\nPflegeversicherung        AN und AG (Kinderlose zahlen mehr) Pflegekassen\nRentenversicherung        AN und AG hälftig               Deutsche Rentenversicherung\nArbeitslosenversicherung  AN und AG hälftig               Bundesagentur für Arbeit\nUnfallversicherung        nur AG                          Berufsgenossenschaften\n\nRechtsform   Haftung                                   Mindestkapital   Organe\nGbR          Gesellschafter unbeschränkt               –                Gesellschafter\nOHG          Gesellschafter unbeschränkt               –                Gesellschafter\nKG           Komplementär unbeschränkt, Kommanditist bis Einlage  –   Komplementär führt\nGmbH         Gesellschaftsvermögen                     25.000 €         Geschäftsführer, Gesellschafterversammlung\nUG (haftungsbeschränkt)  Gesellschaftsvermögen         ab 1 €           wie GmbH (Rücklagenpflicht)\nAG           Gesellschaftsvermögen                     50.000 €         Vorstand, Aufsichtsrat, Hauptversammlung\n\nKündigung im Arbeitsverhältnis: schriftlich (§ 623 BGB), Grundfrist 4 Wochen zum 15. oder Monatsende (§ 622 BGB)\nAusbildung: Probezeit 1–4 Monate; danach Kündigung durch Azubi nur bei Berufsaufgabe/-wechsel mit 4 Wochen Frist',
    checks: [
      ['امتیاز اول WiSo را ثبت کردی.', 'برای هر پاسخ اشتباه کارت یادگیری ساختی.', 'دو جدول را بدون نگاه درست نوشتی.', 'در آزمون WiSo به ۹۰٪ رسیدی.'],
      ['Erster WiSo-Punktestand notiert.', 'Zu jeder falschen Antwort gibt es eine Lernkarte.', 'Beide Tabellen ohne Vorlage richtig geschrieben.', 'Im WiSo-Quiz 90 % erreicht.'],
      ['First WiSo score noted.', 'A flashcard exists for each wrong answer.', 'Both tables written correctly from memory.', 'Reached 90% in the WiSo quiz.']] },
  trouble: [
    [['در سؤال‌های چندگزینه‌ای بین دو گزینه مردد می‌مانی.', 'Bei Auswahlfragen schwankst du zwischen zwei Antworten.', 'You hesitate between two options in multiple choice.'],
     ['کلمه‌های مطلق مثل «immer»، «nie» و «nur» را جدی بگیر؛ اغلب گزینه‌های غلط این‌ها را دارند. سؤال را دقیق بخوان: «trifft NICHT zu» زیاد است. هیچ سؤالی را خالی نگذار.', 'Absolute Wörter wie „immer“, „nie“, „nur“ ernst nehmen – falsche Antworten enthalten sie oft. Genau lesen: „trifft NICHT zu“ kommt häufig vor. Keine Frage leer lassen.', 'Take absolute words like “immer”, “nie”, “nur” seriously – wrong options often contain them. Read carefully: “trifft NICHT zu” is common. Never leave a question blank.']],
    [['قوانین را با هم قاطی می‌کنی (BBiG، BGB، JArbSchG).', 'Gesetze werden verwechselt (BBiG, BGB, JArbSchG).', 'You mix up laws (BBiG, BGB, JArbSchG).'],
     ['برای هر قانون یک «موضوع اصلی» نگه دار: BBiG = آموزش، BGB = قرارداد و فسخ، KSchG = حمایت از فسخ، JArbSchG = زیر ۱۸ سال، BetrVG = شورای کارکنان، ArbZG = زمان کار بزرگسالان.', 'Je Gesetz ein Kernthema merken: BBiG = Ausbildung, BGB = Vertrag und Kündigung, KSchG = Kündigungsschutz, JArbSchG = unter 18, BetrVG = Betriebsrat, ArbZG = Arbeitszeit Erwachsener.', 'Remember one core topic per law: BBiG = training, BGB = contract and termination, KSchG = dismissal protection, JArbSchG = under 18, BetrVG = works council, ArbZG = adult working time.']],
    [['اعداد را فراموش می‌کنی (مهلت‌ها، سرمایه).', 'Zahlen gehen verloren (Fristen, Kapital).', 'You forget numbers (deadlines, capital).'],
     ['فقط اعداد پرتکرار را حفظ کن (۲۵٬۰۰۰، ۵۰٬۰۰۰، ۴ هفته، ۱ تا ۴ ماه، ۵ کارمند، ۸/۴۰ ساعت) و هر روز ۵ دقیقه با کارت مرور کن.', 'Nur die häufigen Zahlen lernen (25.000, 50.000, 4 Wochen, 1–4 Monate, 5 Beschäftigte, 8/40 Stunden) und täglich 5 Minuten mit Karten wiederholen.', 'Memorise only the frequent numbers (25,000, 50,000, 4 weeks, 1–4 months, 5 employees, 8/40 hours) and review with cards for 5 minutes daily.']]],
  decide: [
    [['وقت کم تا آزمون', 'Wenig Zeit bis zur Prüfung', 'Little time before the exam'], ['آزمون تمرینی + کارت‌های اشتباه؛ کتاب کامل نخوان.', 'Übungsquiz + Fehlerkarten; kein komplettes Buch lesen.', 'Practice quiz + error cards; don’t read a whole book.']],
    [['در اتریش', 'In Österreich', 'In Austria'], ['قوانین فرق دارند (مثلاً BAG به جای BBiG، ASVG برای بیمهٔ اجتماعی)؛ از مطالب WKO/AK اتریش استفاده کن.', 'Die Gesetze unterscheiden sich (z. B. BAG statt BBiG, ASVG für die Sozialversicherung) – Unterlagen von WKO/AK nutzen.', 'Laws differ (e.g. BAG instead of BBiG, ASVG for social insurance) – use WKO/AK materials.']]],
  pitfalls: [
    ['خواندن سطحی «NICHT» در سؤال.', '„NICHT“ in der Frage überlesen.', 'Overlooking “NICHT” in the question.'],
    ['اعتماد به اعداد قدیمی از منابع کهنه؛ همیشه منبع جدید.', 'Alten Zahlen aus veralteten Quellen vertrauen – immer aktuelle Quelle.', 'Trusting old figures from outdated sources – always use current ones.'],
    ['مطالعهٔ WiSo فقط شب قبل از آزمون.', 'WiSo erst am Vorabend lernen.', 'Studying WiSo only the night before.']],
  iv: [
    [['پنج شاخهٔ بیمهٔ اجتماعی آلمان؟', 'Die fünf Zweige der deutschen Sozialversicherung?', 'The five branches of German social insurance?'], ['درمان، مراقبت، بازنشستگی، بیکاری و حوادث کار.', 'Kranken-, Pflege-, Renten-, Arbeitslosen- und Unfallversicherung.', 'Health, long-term care, pension, unemployment and accident insurance.']],
    [['فرق GmbH و GbR از نظر مسئولیت؟', 'Unterschied GmbH und GbR bei der Haftung?', 'GmbH vs GbR liability?'], ['در GmbH فقط دارایی شرکت پاسخ‌گوست؛ در GbR شرکا با کل دارایی شخصی خود.', 'Bei der GmbH haftet nur das Gesellschaftsvermögen, bei der GbR haften die Gesellschafter mit ihrem gesamten Privatvermögen.', 'In a GmbH only company assets are liable; in a GbR partners are liable with all their private assets.']],
    [['دورهٔ آزمایشی در آموزش حرفه‌ای چقدر است؟', 'Wie lang ist die Probezeit in der Ausbildung?', 'How long is probation in vocational training?'], ['حداقل یک و حداکثر چهار ماه؛ در آن هر دو طرف بدون مهلت و دلیل می‌توانند فسخ کنند.', 'Mindestens einen, höchstens vier Monate; in dieser Zeit können beide Seiten fristlos und ohne Grund kündigen.', 'At least one and at most four months; either side may terminate without notice or reason during it.']]],
  sources: [['Berufsbildungsgesetz (BBiG)', 'https://www.gesetze-im-internet.de/bbig_2005/'], ['§ 622 BGB Kündigungsfristen', 'https://www.gesetze-im-internet.de/bgb/__622.html'], ['Deutsche Sozialversicherung – Überblick', 'https://www.deutsche-sozialversicherung.de/']]
},

{
  id: 'ap-projekt', part: 3,
  title: ['پروژهٔ آزمون: درخواست، مستندسازی، ارائه و گفت‌وگوی تخصصی', 'Prüfungsprojekt: Antrag, Dokumentation, Präsentation und Fachgespräch', 'Exam project: proposal, documentation, presentation and technical discussion'],
  goal: ['یک موضوع پروژهٔ مناسب انتخاب کنی، درخواست پروژه را طوری بنویسی که تأیید شود، مستندسازی ساخت‌یافته با مقایسهٔ گزینه‌ها و محاسبهٔ هزینه بنویسی و ارائه و گفت‌وگوی تخصصی را آماده کنی.', 'Du wählst ein passendes Projektthema, schreibst einen genehmigungsfähigen Projektantrag, eine strukturierte Dokumentation mit Variantenvergleich und Kostenrechnung und bereitest Präsentation und Fachgespräch vor.', 'Choose a suitable project topic, write an approvable proposal, structured documentation with option comparison and cost calculation, and prepare the presentation and technical discussion.'],
  why: ['پروژه نیمی از نمرهٔ نهایی است. بیشتر نمرهٔ ازدست‌رفته از موضوع ضعیف (فقط نصب)، نبود مقایسهٔ گزینه‌ها و تصمیم مستدل، یا ارائهٔ بی‌ساختار می‌آید، نه از کمبود فنی.', 'Das Projekt ist die halbe Endnote. Die meisten verlorenen Punkte kommen von schwachen Themen (reine Installation), fehlendem Variantenvergleich und unbegründeten Entscheidungen oder unstrukturierten Präsentationen – nicht von fehlender Technik.', 'The project is half the final grade. Most lost points come from weak topics (pure installation), missing option comparison and unjustified decisions, or unstructured presentations – not lack of technical skill.'],
  know: [
    ['موضوع خوب: مسئلهٔ واقعی شرکت با چند راه‌حل ممکن که باید سنجیده و تصمیم گرفته شود (مثلاً «معرفی پشتیبان Immutable برای ۱۵ سرور»، «جایگزینی WLAN با 802.1X»، «Monitoring با Checkmk»). «نصب ویندوز روی ۲۰ کامپیوتر» به‌تنهایی کافی نیست.', 'Gutes Thema: ein echtes Problem des Betriebs mit mehreren möglichen Lösungen, die bewertet und entschieden werden müssen (z. B. „Einführung unveränderbarer Backups für 15 Server“, „Umstellung des WLANs auf 802.1X“, „Monitoring mit Checkmk“). „Windows auf 20 PCs installieren“ allein reicht nicht.', 'A good topic: a real company problem with several possible solutions that must be evaluated and decided (e.g. “introducing immutable backups for 15 servers”, “moving WLAN to 802.1X”, “monitoring with Checkmk”). “Installing Windows on 20 PCs” alone isn’t enough.'],
    ['درخواست پروژه (Projektantrag): عنوان، وضعیت فعلی (Ist)، هدف (Soll)، محدوده، مراحل با زمان (جمعاً حداکثر ۴۰ ساعت، شامل مستندسازی)، و نتیجهٔ قابل‌تحویل. IHK آن را قبل از شروع تأیید می‌کند.', 'Projektantrag: Titel, Ist-Zustand, Soll-Zustand, Abgrenzung, Phasen mit Zeitplan (insgesamt höchstens 40 Stunden inkl. Dokumentation) und Ergebnis. Die IHK genehmigt ihn vor Beginn.', 'Project proposal: title, current state, target state, scope, phases with time plan (max 40 hours total incl. documentation) and deliverable. The IHK approves it before you start.'],
    ['ساختار مستندسازی: مقدمه و محیط پروژه، تحلیل (Ist، Soll، الزامات)، طراحی و مقایسهٔ گزینه‌ها (Nutzwertanalyse)، محاسبهٔ هزینه و صرفهٔ اقتصادی، اجرا، آزمایش و تحویل، نتیجه و درس‌آموزی، پیوست‌ها. صفحه‌ها و قالب را از IHK خودت بپرس.', 'Gliederung der Dokumentation: Einleitung und Projektumfeld, Analyse (Ist, Soll, Anforderungen), Entwurf und Variantenvergleich (Nutzwertanalyse), Kosten- und Wirtschaftlichkeitsbetrachtung, Durchführung, Test und Übergabe, Fazit und Lessons Learned, Anhang. Seitenumfang und Form bei der eigenen IHK erfragen.', 'Documentation outline: introduction and project context, analysis (current, target, requirements), design and option comparison (weighted scoring), cost and economic evaluation, implementation, test and handover, conclusion and lessons learned, appendix. Ask your IHK about page limits and format.'],
    ['ارائه حداکثر ۱۵ دقیقه: مسئله، هدف، گزینه‌ها و تصمیم، اجرای مهم‌ترین قسمت، نتیجه و درس‌آموزی. یک ایده در هر اسلاید، تصویر به جای متن، و تمرین با زمان‌سنج.', 'Präsentation höchstens 15 Minuten: Problem, Ziel, Varianten und Entscheidung, wichtigster Umsetzungsteil, Ergebnis und Lessons Learned. Eine Idee pro Folie, Grafiken statt Text, mit Stoppuhr üben.', 'Presentation max 15 minutes: problem, goal, options and decision, key implementation part, result and lessons learned. One idea per slide, visuals instead of text, practise with a timer.'],
    ['گفت‌وگوی تخصصی (۱۵ دقیقه): از پروژه شروع و به دانش عمومی رشته گسترش می‌یابد. «چرا این گزینه و نه آن؟»، «اگر X خراب شود؟»، «امنیت و DSGVO؟». صادقانه بگو اگر نمی‌دانی و استدلال کن چطور پیدا می‌کنی.', 'Fachgespräch (15 Minuten): beginnt beim Projekt und weitet sich aufs Berufsfeld aus. „Warum diese Variante und nicht jene?“, „Was, wenn X ausfällt?“, „Sicherheit und DSGVO?“. Ehrlich sagen, wenn man etwas nicht weiß, und erklären, wie man es herausfinden würde.', 'Technical discussion (15 minutes): starts at your project and widens to the field. “Why this option and not that?”, “what if X fails?”, “security and GDPR?”. Say honestly when you don’t know and explain how you’d find out.']],
  lab: { vm: 'Textverarbeitung/Docs + Präsentation', shell: 'Vorlagen',
    steps: [
      ['سه ایدهٔ پروژه از کار واقعی‌ات بنویس و برای هر کدام بررسی کن: مسئلهٔ واقعی، چند گزینه، تصمیم، قابل اجرا در ۴۰ ساعت.', 'بهترین ایده را به‌صورت درخواست پروژه با قالب نمونه بنویس.', 'برای بخش تصمیم، Nutzwertanalyse با حداقل دو گزینه و یک محاسبهٔ هزینه یا Amortisation آماده کن.', 'طرح ۸ اسلایدی ارائه را بنویس و یک بار با زمان‌سنج تمرین کن.', 'ده سؤال احتمالی گفت‌وگوی تخصصی دربارهٔ پروژه‌ات بنویس و پاسخ کوتاه هر کدام را آماده کن.'],
      ['Drei Projektideen aus deiner Praxis notieren und je prüfen: echtes Problem, mehrere Varianten, Entscheidung, in 40 Stunden machbar.', 'Die beste Idee als Projektantrag nach der Vorlage schreiben.', 'Für die Entscheidung eine Nutzwertanalyse mit mindestens zwei Varianten und eine Kosten- oder Amortisationsrechnung vorbereiten.', 'Einen 8-Folien-Ablauf der Präsentation schreiben und einmal mit Stoppuhr üben.', 'Zehn mögliche Fachgesprächsfragen zum eigenen Projekt notieren und kurze Antworten vorbereiten.'],
      ['Write three project ideas from your real work and check each: real problem, several options, a decision, doable in 40 hours.', 'Write the best one as a proposal using the template.', 'For the decision prepare a weighted scoring with at least two options and a cost or payback calculation.', 'Outline an 8-slide presentation and rehearse once with a timer.', 'Write ten likely discussion questions about your project with short answers.']],
    code: 'PROJEKTANTRAG (Vorlage)\n1 Projektbezeichnung: Einführung eines unveränderbaren Backups für die Server der Muster GmbH\n2 Ist-Zustand: 15 Server, tägliches Backup auf NAS im selben Netz, kein Offline-/Immutable-Stand, Restore nie getestet\n3 Soll-Zustand: 3-2-1-1-0-konformes Backup mit Hardened Repository, dokumentierter Restore-Test, RPO 24 h, RTO 4 h\n4 Abgrenzung: keine Neuanschaffung der Server, keine Änderung der Anwendungen\n5 Zeitplanung (40 h)\n   Analyse Ist/Soll, Anforderungen ...................... 5 h\n   Variantenvergleich (Veeam Hardened Repo / Cloud Immutable / Tape) + Nutzwertanalyse + Kosten ... 7 h\n   Umsetzung (Repository, Jobs, Backup Copy) .......... 12 h\n   Test (Restore-Test, Unveränderbarkeit) ............. 5 h\n   Übergabe, Einweisung, Runbook ....................... 3 h\n   Projektdokumentation ............................... 8 h\n6 Ergebnis: funktionierendes System, Restore-Protokoll, Runbook, Dokumentation\n\nPRÄSENTATION (8 Folien, 15 Min.)\n1 Titel + Ich  2 Ausgangslage (Bild: altes Backup im selben Netz)  3 Ziel und Anforderungen\n4 Varianten + Nutzwertanalyse  5 Kosten/Amortisation  6 Umsetzung (Architekturbild)\n7 Test: Restore in X Minuten, Löschversuch abgewiesen  8 Fazit, Lessons Learned, Ausblick\n\nFACHGESPRÄCH – mögliche Fragen\nWarum Hardened Repository statt Cloud? | Was ist RPO/RTO? | Was passiert bei Ransomware auf dem Veeam-Server?\nWie prüfst du ein Backup? | Warum XFS? | Welche DSGVO-Aspekte gibt es? | Was würdest du heute anders machen?',
    checks: [
      ['ایدهٔ انتخابی همهٔ معیارها (مسئلهٔ واقعی، گزینه‌ها، تصمیم، ۴۰ ساعت) را دارد.', 'درخواست پروژه همهٔ بخش‌ها و زمان‌بندی با جمع ۴۰ ساعت را دارد.', 'Nutzwertanalyse و محاسبهٔ هزینه برای تصمیم آماده است.', 'ارائه در ۱۵ دقیقه یا کمتر تمام شد و ده سؤال احتمالی با پاسخ داری.'],
      ['Die gewählte Idee erfüllt alle Kriterien (echtes Problem, Varianten, Entscheidung, 40 h).', 'Der Antrag hat alle Abschnitte und eine Zeitplanung mit Summe 40 h.', 'Nutzwertanalyse und Kostenrechnung für die Entscheidung liegen vor.', 'Die Präsentation dauerte höchstens 15 Minuten, zehn Fragen mit Antworten sind vorbereitet.'],
      ['The chosen idea meets all criteria (real problem, options, decision, 40 h).', 'The proposal has all sections and a time plan summing to 40 h.', 'Weighted scoring and cost calculation for the decision are ready.', 'The presentation took 15 minutes or less and ten questions with answers are prepared.']] },
  trouble: [
    [['درخواست پروژه رد شد یا با شرط برگشت.', 'Projektantrag abgelehnt oder mit Auflagen zurück.', 'Proposal rejected or returned with conditions.'],
     ['دلیل معمول: سهم تصمیم و برنامه‌ریزی خیلی کم (فقط اجرا)، حجم بیش یا کم از ۴۰ ساعت، یا محدودهٔ نامشخص. مقایسهٔ گزینه‌ها و تحلیل را صریح‌تر کن، زمان‌بندی را واقع‌بینانه کن و شرط‌ها را دقیق اجرا کن.', 'Meist: zu wenig Planungs- und Entscheidungsanteil (nur Umsetzung), Umfang über oder unter 40 h oder unklare Abgrenzung. Variantenvergleich und Analyse deutlicher machen, Zeitplan realistisch planen, Auflagen genau umsetzen.', 'Usually: too little planning and decision work (just implementation), scope over or under 40 h, or unclear boundaries. Make option comparison and analysis explicit, plan time realistically and follow conditions exactly.']],
    [['وسط پروژه چیزی پیش‌بینی‌نشده رخ داد (سخت‌افزار نرسید، تغییر برنامه).', 'Mitten im Projekt passiert Unvorhergesehenes (Hardware fehlt, Planänderung).', 'Something unexpected happens mid-project (hardware missing, plan change).'],
     ['تغییر را با تاریخ و دلیل مستند کن، با مسئول آموزش و در صورت لزوم IHK هماهنگ کن و در مستندسازی در بخش «Soll-Ist-Vergleich» توضیح بده که چطور واکنش نشان دادی؛ مدیریت درست مشکل امتیاز مثبت دارد.', 'Abweichung mit Datum und Grund dokumentieren, mit Ausbilder und ggf. IHK abstimmen und in der Dokumentation im Soll-Ist-Vergleich erklären, wie du reagiert hast – gutes Problemmanagement bringt Punkte.', 'Document the deviation with date and reason, coordinate with your trainer and the IHK if needed, and explain your response in the plan-vs-actual section – good problem handling earns points.']],
    [['در گفت‌وگوی تخصصی جواب سؤالی را نمی‌دانی.', 'Im Fachgespräch kennst du eine Antwort nicht.', 'In the discussion you don’t know an answer.'],
     ['آرام بمان، بگو «Das weiß ich nicht genau, ich würde es so herausfinden …» و منطق پیدا کردن را توضیح بده (مستند سازنده، آزمایش در Lab، Log). حدس با اطمینان کاذب بدتر از صداقت است.', 'Ruhig bleiben, „Das weiß ich nicht genau, ich würde es so herausfinden …“ sagen und den Weg erklären (Herstellerdoku, Labortest, Logs). Selbstsicheres Raten ist schlechter als Ehrlichkeit.', 'Stay calm, say “Das weiß ich nicht genau, ich würde es so herausfinden …” and explain the path (vendor docs, lab test, logs). Confident guessing is worse than honesty.']]],
  decide: [
    [['شرکت پروژهٔ بزرگ‌تری دارد', 'Der Betrieb hat ein größeres Projekt', 'The company has a bigger project'], ['یک بخش مستقل و قابل‌تحویل را برای خودت جدا کن که در ۴۰ ساعت تمام شود و تصمیم خودت را داشته باشد.', 'Einen eigenständigen, abgrenzbaren Teil herauslösen, der in 40 h fertig wird und eigene Entscheidungen enthält.', 'Carve out an independent, deliverable part that finishes in 40 h and contains your own decisions.']],
    [['دو موضوع خوب داری', 'Zwei gute Themen', 'Two good topics'], ['موضوعی را انتخاب کن که گزینه‌های واقعی‌تر و محاسبهٔ هزینهٔ روشن‌تری دارد و در آن خودت تصمیم‌گیرنده بودی.', 'Das Thema mit echteren Varianten, klarerer Kostenrechnung und bei dem du selbst entschieden hast.', 'The one with more genuine options, a clearer cost calculation and where you were the decision maker.']]],
  pitfalls: [
    ['پروژهٔ «فقط نصب» بدون مقایسهٔ گزینه‌ها.', '„Nur Installation“ ohne Variantenvergleich.', 'An “installation only” project without option comparison.'],
    ['مستندسازی را تا آخر نگه داشتن.', 'Dokumentation bis zum Schluss aufschieben.', 'Leaving documentation to the very end.'],
    ['اسلایدهای پرمتن و خواندن از روی اسلاید.', 'Textlastige Folien und Ablesen.', 'Text-heavy slides and reading from them.']],
  iv: [
    [['یک پروژهٔ خوب Systemintegration چه ویژگی‌ای دارد؟', 'Was macht ein gutes Systemintegrations-Projekt aus?', 'What makes a good system integration project?'], ['مسئلهٔ واقعی، چند گزینهٔ ممکن، تصمیم مستدل با Nutzwertanalyse و هزینه، اجرا و آزمایش قابل‌اندازه‌گیری، و حجم واقع‌بینانه برای ۴۰ ساعت.', 'Ein echtes Problem, mehrere Varianten, begründete Entscheidung per Nutzwertanalyse und Kosten, messbare Umsetzung und Tests und ein realistischer Umfang für 40 Stunden.', 'A real problem, several options, a justified decision via weighted scoring and cost, measurable implementation and testing and a realistic scope for 40 hours.']],
    [['ساختار ارائهٔ ۱۵ دقیقه‌ای تو؟', 'Aufbau deiner 15-Minuten-Präsentation?', 'Structure of your 15-minute presentation?'], ['مسئله، هدف، گزینه‌ها و تصمیم، اجرای اصلی، آزمایش و نتیجه، درس‌آموزی و آینده – با اسلایدهای تصویری و تمرین زمان‌دار.', 'Problem, Ziel, Varianten und Entscheidung, Kernumsetzung, Test und Ergebnis, Lessons Learned und Ausblick – mit Grafikfolien und geübtem Timing.', 'Problem, goal, options and decision, core implementation, test and result, lessons learned and outlook – with visual slides and rehearsed timing.']],
    [['اگر در گفت‌وگو چیزی را ندانی؟', 'Wenn du im Fachgespräch etwas nicht weißt?', 'If you don’t know something in the discussion?'], ['صادقانه می‌گویم و توضیح می‌دهم چطور جواب را پیدا می‌کنم؛ این نشان‌دهندهٔ روش کار حرفه‌ای است.', 'Ehrlich sagen und erklären, wie ich die Antwort finden würde – das zeigt professionelles Vorgehen.', 'Say so honestly and explain how I’d find the answer – that shows a professional approach.']]],
  sources: [['DIHK – Umsetzungshilfe IT-Berufe (Projektarbeit)', 'https://www.ihk.de/blueprint/servlet/resource/blob/6945168/0424ce44eab4c49eab8b0c078fe7d796/dihk-umsetzungshilfe-it-berufe-data.pdf'], ['FIAusbV § 20 – Projekt Systemintegration', 'https://www.gesetze-im-internet.de/fiausbv/__20.html'], ['Lernstrecke Virtualisierung, Backup und Monitoring (Projektideen)', 'https://arefi2027.github.io/arefi-itpraxis/#k-infra']]
}
);
})();
